import openpyxl
import pandas as pd
from collections import OrderedDict

wb = openpyxl.load_workbook('/app/Market_Data.xlsx')

# ---- Parse Methodology sheet ----
method_ws = wb['Methodology']

# Row 2: Segment/Source header, row 2 cols B onwards = source names
# Row 3: source types (CDP, S&P, etc)
# Rows 4-13: segments with weights
# Column A = segment name, Column B = source name
# Remaining columns: source columns with weights

# Get source names from Methodology row 2, columns B onwards
method_source_names = []
for col in range(2, method_ws.max_column + 1):  # col 2=B
    val = method_ws.cell(row=2, column=col).value
    if val is not None:
        method_source_names.append(val)
print("Methodology sources:", method_source_names)

# Get segments and their weights
# Column A has segment names, Column B has source name, remaining cols have weights
segments = OrderedDict()
for row in range(4, method_ws.max_row + 1):
    seg_name = method_ws.cell(row=row, column=1).value
    src_name = method_ws.cell(row=row, column=2).value
    if seg_name is None or src_name is None:
        continue
    if seg_name == 'Total':
        continue
    if seg_name not in segments:
        segments[seg_name] = {}
    # Get weights from remaining columns
    for col in range(3, method_ws.max_column + 1):
        weight = method_ws.cell(row=row, column=col).value
        if weight is not None and weight != 0:
            segments[seg_name][method_source_names[col - 2]] = float(weight)

print("Segments and their sources:")
for seg, srcs in segments.items():
    print(f"  {seg}: {srcs}")

# ---- Parse RawData sheet ----
raw_ws = wb['RawData']

# Find the row with source names (YY header row)
source_col_names = []
data_start_row = None
for row in range(1, raw_ws.max_row + 1):
    first_cell = raw_ws.cell(row=row, column=1).value
    if first_cell == 'YY':
        data_start_row = row
        # Get source names from this row (col 2 onwards)
        for col in range(2, raw_ws.max_column + 1):
            val = raw_ws.cell(row=row, column=col).value
            source_col_names.append(val)
        break

print("\nRawData source names:", source_col_names)
print(f"Data starts at row: {data_start_row}")

# Read data from data_start_row+1 onwards
source_data = {}  # {source_name: {year: value}}
for src in source_col_names:
    source_data[src] = {}

for row in range(data_start_row + 1, raw_ws.max_row + 1):
    year_cell = raw_ws.cell(row=row, column=1).value
    if year_cell is None or not isinstance(year_cell, (int, float)):
        continue
    year = int(year_cell)
    for col in range(2, raw_ws.max_column + 1):
        src = source_col_names[col - 2]
        val = raw_ws.cell(row=row, column=col).value
        # Handle string values (formulas) - treat as None
        if val is None or isinstance(val, str):
            val = None
        else:
            try:
                val = float(val)
            except (ValueError, TypeError):
                val = None
        source_data[src][year] = val

# Print sample data
for src in source_col_names[:5]:
    print(f"\n{src}:")
    for year in sorted(source_data[src].keys()):
        print(f"  {year}: {source_data[src][year]}")

# ---- Calculate YoY growth rates ----
# Growth rate = (current - prev) / prev * 100
# Only if both current and previous exist and prev != 0
growth_rates = {}  # {source_name: {year: growth_rate_pct}}

for src in source_col_names:
    growth_rates[src] = {}
    years = sorted(source_data[src].keys())
    for i in range(1, len(years)):
        curr_year = years[i]
        prev_year = years[i - 1]
        curr_val = source_data[src][curr_year]
        prev_val = source_data[src][prev_year]
        if curr_val is not None and prev_val is not None and prev_val != 0:
            gr = (curr_val - prev_val) / prev_val * 100
            growth_rates[src][curr_year] = gr

# Print growth rates for key sources
print("\nGrowth rates for Agriculture (first few):")
for year in sorted(growth_rates['Agriculture'].keys()):
    print(f"  {year}: {growth_rates['Agriculture'][year]:.4f}%")

print("\nGrowth rates for Auto Production:")
for year in sorted(growth_rates['Auto Production'].keys()):
    print(f"  {year}: {growth_rates['Auto Production'][year]:.4f}%")

print("\nGrowth rates for Air Bus:")
for year in sorted(growth_rates['Air Bus'].keys()):
    print(f"  {year}: {growth_rates['Air Bus'][year]:.4f}%")

print("\nGrowth rates for Steel Production:")
for year in sorted(growth_rates['Steel Production'].keys()):
    print(f"  {year}: {growth_rates['Steel Production'][year]:.4f}%")

print("\nGrowth rates for MRO:")
for year in sorted(growth_rates['MRO'].keys()):
    print(f"  {year}: {growth_rates['MRO'][year]:.4f}%")

# ---- Calculate segment growth rates ----
# Years to output: 2015 to 2024
years = list(range(2015, 2025))
segment_order = list(segments.keys())  # same order as in Methodology

results = {'Year': years}

for seg in segment_order:
    results[seg] = []
    for year in years:
        source_grs = []
        all_valid = True
        for src, weight in segments[seg].items():
            if src not in growth_rates:
                all_valid = False
                break
            if year not in growth_rates[src]:
                all_valid = False
                break
            source_grs.append((weight, growth_rates[src][year]))

        if not all_valid:
            results[seg].append('N/A')
        else:
            weighted_sum = sum(w * gr for w, gr in source_grs)
            results[seg].append(round(weighted_sum, 1))

print("\n\nFinal Results:")
for seg in segment_order:
    print(f"\n{seg}:")
    for year in years:
        print(f"  {year}: {results[seg][years.index(year)]}")

# ---- Save to Excel ----
df = pd.DataFrame(results)
df.to_excel('/app/segment_growth_rates.xlsx', index=False)
print("\nSaved to /app/segment_growth_rates.xlsx")
